import { PromoCard, PromoCardData } from "./Parse";
import { secondaryCTA } from "../../CTA/Render";
import { localizeHref, sanitize, federateUrl } from "../../../Utils/Utils";
import { svgIcon } from "../../SvgIcon/Render";

export const promoCard = ({ card }: PromoCard): HTML => renderCard(card);

const renderCard = ({
  bgImageAlt,
  bgImageSrc,
  iconAlt,
  iconSrc,
  title,
  cta,
  priceText,
  priceHref,
  isPriceMerchLink,
  isPriceMasLink,
}: PromoCardData): HTML => {
  const merchClass = isPriceMerchLink ? ' class="merch"' : '';
  const priceDescribedBy = isPriceMerchLink || isPriceMasLink
    ? ` price-${sanitize(title)}` : '';
  const ctaDescribedBy = `title-${sanitize(title)}${priceDescribedBy}`;
  return `
  <article class="promo-card" daa-lh="promo-card">
    ${
      bgImageSrc
        ? `<picture class="promo-card__bg">
             <img 
              loading="lazy"
              src="${federateUrl(bgImageSrc)}"
              alt="${bgImageAlt}"
              class="promo-card__bg-image"
            >
           </picture>`
        : ""
    }

    <div class="promo-card__content">
      ${svgIcon(
        { src: iconSrc, alt: iconAlt },
        { imgClass: 'promo-card__icon-image', pictureClass: 'promo-card__icon' },
      )}
      <div class="promo-card__text-content">
        ${priceHref && (isPriceMerchLink || isPriceMasLink) ? `<p id="price-${sanitize(title)}" class="promo-card__price">
          <a href="${localizeHref(priceHref)}"${merchClass}>${priceText}</a>
        </p>` : ''}
        <h2 id="title-${sanitize(title)}" class="promo-card__title" role="heading" aria-level="2">
          ${title}
        </h2>
        ${
          cta === null
            ? ""
            : `<div class="promo-card__cta">
                 ${secondaryCTA({...cta, ariaAttrs: { 'aria-describedby': ctaDescribedBy }})}
               </div>`
        }
      </div>
    </div>
  </article>
`.trim();
}

