type GlobalNavigation = {
  closeEverything: () => void;
  reloadUnav: () => void;
  reloadProfile: () => void;
  getGnavTopPosition: () => number;
  setGnavTopPosition: (_: number) => void;
  getGnavHeight: () => number;
  errors: Set<RecoverableError>;
};

export type Input = {
  gnavSource: URL;
  gnavTop?: number;
  mepMartech?: string;
  isLocalNav: boolean;
  mountpoint: HTMLElement;
  unavEnabled: boolean;
  // Host IMS readiness; only UNAV waits, not the navigation shell.
  imsReady?: Promise<void>;
  // Host-owned AUP SDK (e.g. Milo's, which also renders AUP dialogs and
  // publishes readiness for merch CTAs). When provided, UNAV uses it and
  // federal does not load or configure its own SDK instance.
  fetchAUPSDKInstance?: () => Promise<unknown>;
  placeholders: Promise<Map<string, string>>;
  miloConfig?: MiloConfig;
  // Geo-validated market for the unav and drives the cart. String or a
  // promise the host resolves in parallel;
  countryCode?: string | Promise<string | undefined>;
  lingoRegion?: LingoLocaleConfig;
  // We deliberately stay less entangled with MEP than milo's own gnav
  // implementation (e.g. we don't add manifestId to the body). The host is
  // expected to supply `handleCommands` (applied to each freshly-fetched,
  // detached fragment body) and, if fragment-swap manifests targeting
  // content nested inside the gnav are needed (e.g. a product-card
  // fragment), `resolveFragmentHref` — see PersonalizationConfig in Utils.ts.
  personalization: PersonalizationConfig;
  localizeLink?: LocalizeLink;
  // Async companion to localizeLink — runs milo's decorateLinksAsync over the
  // raw fetched body pre-parse (lingo regionalization + mep-lingo prefix).
  decorateBody?: DecorateBody;
  // Host-injected Milo commerce decorators; falls back to a config.base import.
  merchDecorators?: MerchDecorators;
  // Milo's appendHtmlToLink: adds `.html` to extensionless internal links
  // when config.useDotHtml is on. Runs pre-localize to mirror c1.
  appendHtmlToLink?: (link: HTMLAnchorElement) => void;
  convertStageLinks?: (args: {
    anchors: HTMLAnchorElement[];
    hostname: string;
    href: string;
  }) => void;
  // Host-injected loader for Milo's brand-concierge-global block. Called with
  // the authored `.brand-concierge-global` block from the gnav source when
  // `gnav-brand-concierge` is on; the block mounts its UI into the
  // `.feds-bc-wrapper`.
  loadBrandConcierge?: LoadBrandConcierge;
};

// Detaches the brand-concierge-global block from the nav (so it isn't parsed
// as a nav item) and returns it for separate loading into `.feds-bc-wrapper`,
// mirroring c1 where the block never enters the page. The block may be
// authored inline, as a `#_inline` fragment (already expanded upstream), or as
// a plain fragment link — either inside a `.brand-concierge-global` block or,
// when enabled, as a bare link.
const resolveBrandConciergeBlock = async (
  mainNav: HTMLElement,
): Promise<HTMLElement | null> => {
  const brandConciergeEnabled = getMetadata('gnav-brand-concierge') === 'on';
  let brandConciergeBlock
    = mainNav.querySelector<HTMLElement>('.brand-concierge-global');

  // Detected regardless of metadata so a disabled BC link is still stripped
  // from the nav below rather than rendered as a stray item.
  const brandConciergeLink = (brandConciergeBlock ?? mainNav)
    .querySelector<HTMLAnchorElement>(
      'a[href*="/fragments/"][href*="brand-concierge"]',
    );
  // Element stripped from the nav so the block/link isn't parsed as a nav item.
  let brandConciergeWrapper: HTMLElement | null
    = brandConciergeBlock ?? brandConciergeLink;

  // Only resolve/populate the block's content when enabled; when disabled the
  // link is still stripped below so it never renders.
  if (brandConciergeEnabled && brandConciergeLink) {
    try {
      const fragmentBody = await fetchAndProcessPlainHTML(
        new URL(brandConciergeLink.href.split('#')[0]),
      );
      if (!(fragmentBody instanceof IrrecoverableError)) {
        const inner = fragmentBody.querySelector<HTMLElement>('.brand-concierge-global')
          ?? fragmentBody;
        // A bare link has no block wrapper; synthesize one for the host loader.
        if (!brandConciergeBlock) {
          brandConciergeBlock = document.createElement('div');
          brandConciergeBlock.className = 'brand-concierge-global';
        }
        brandConciergeBlock.replaceChildren(...inner.children);
      }
    } catch (error) {
      lanaLog(`Failed to resolve brand concierge fragment: ${error}`);
    }
  }

  while (brandConciergeWrapper?.parentElement
    && brandConciergeWrapper.parentElement !== mainNav) {
    brandConciergeWrapper = brandConciergeWrapper.parentElement;
  }
  brandConciergeWrapper?.remove();

  return brandConciergeBlock;
};

// Runtime guard for callers crossing the JS boundary, where the compile-time
// `Input` typing isn't enforced. Validates the required fields have the right
// runtime shape; optional fields are left to their call sites.
const validateInput = (input: Input): IrrecoverableError | null => {
  if (!(input.gnavSource instanceof URL)) {
    return new IrrecoverableError('gnavSource needs to be a URL object');
  }
  if (!(input.mountpoint instanceof HTMLElement)) {
    return new IrrecoverableError('mountpoint needs to be an HTMLElement');
  }
  if (typeof input.isLocalNav !== 'boolean') {
    return new IrrecoverableError('isLocalNav needs to be a boolean');
  }
  if (typeof input.unavEnabled !== 'boolean') {
    return new IrrecoverableError('unavEnabled needs to be a boolean');
  }
  if (!(input.placeholders instanceof Promise)) {
    return new IrrecoverableError('placeholders needs to be a Promise');
  }
  if (typeof input.personalization !== 'object' || input.personalization === null) {
    return new IrrecoverableError('personalization needs to be an object');
  }
  return null;
};

// Non-function values from JS callers are ignored.
const getHostFetchAUPSDKInstance = (
  input: Input,
): (() => Promise<unknown>) | undefined => (
  typeof input.fetchAUPSDKInstance === 'function' ? input.fetchAUPSDKInstance : undefined
);

export const main = async (
  input: Input
): Promise<GlobalNavigation | IrrecoverableError> => {
  const inputError = validateInput(input);
  if (inputError !== null) {
    lanaLog(inputError.message);
    throw inputError;
  }

  const {
    mountpoint,
    unavEnabled,
    miloConfig,
    personalization
  } = input;

  try {
    setMiloConfig(miloConfig);
  } catch (error) {
    lanaLog(`Failed to initialize MiloConfig: ${error}`);
    throw new IrrecoverableError(`Failed to initialize MiloConfig: ${error}`);
  }

  setPersonalizationConfig(personalization);
  setLocalizeLink(input.localizeLink ?? ((link: string): string => link));
  setDecorateBody(async (body): Promise<void> => {
    const anchors = [...body.querySelectorAll<HTMLAnchorElement>('a')];
    anchors.forEach((anchor) => input.appendHtmlToLink?.(anchor));
    await input.decorateBody?.(body);
    // Localize before stage conversion so cross-domain prod links (helpx/
    // business) carry a locale prefix convertStageLinks preserves; at render
    // the host is already rewritten to *.stage and no longer matches
    // prodDomains. Skipped when the host localized the body itself (e.g. the
    // lingo decorateBody) to avoid re-processing regionalized links.
    if (!input.decorateBody) {
      const localize = getLocalizeLink();
      anchors.forEach((a) => {
        if (!a.href.includes('#_dnt')) a.href = localize(a.href);
      });
    }
    input.convertStageLinks?.({
      anchors,
      hostname: window.location.hostname,
      href: window.location.href,
    });
  });
  if (input.merchDecorators) setMerchDecorators(input.merchDecorators);
  if (input.loadBrandConcierge) setLoadBrandConcierge(input.loadBrandConcierge);
  // Normalize null → undefined so the stored state matches the
  // `LingoLocaleConfig | undefined` invariant even if a JS caller passes null.
  setLingoLocaleConfig(input.lingoRegion ?? undefined);

  // We kick off the request for the federal placeholders in parallel
  setPlaceholders(combineWithFederalPlaceholders(input));

  // Kick off AUP SDK init in parallel with gnav fetch/parse/render and the
  // UniversalNav.js download when the host has no pending IMS initialization.
  // Otherwise loadUnav() starts AUP after the host's readiness promise settles.
  if (unavEnabled && input.imsReady === undefined
    && getHostFetchAUPSDKInstance(input) === undefined) preloadAupSdk();

  const initial = await getInitialHTML(input)
  if (initial instanceof IrrecoverableError) {
    lanaLog(initial.message);
    throw initial;
  }
  const { mainNav, promoBarEl } = initial;
  if (mainNav instanceof IrrecoverableError) {
    lanaLog(mainNav.message);
    throw mainNav;
  }

  // The legacy profile sources its sign-in dropdown and "local menu" from an
  // authored `.profile` block. Capture it (and remove it) before parse so the
  // component parser doesn't misread it as a Link/Text component.
  const rawProfileElem = mainNav.querySelector('.profile');
  rawProfileElem?.remove();

  // Mirror milo: the legacy profile is the non-UniversalNav path — it renders
  // only when unav is off AND a `.profile` block was authored (a page opts out
  // by not authoring one). Otherwise `loadUnav` owns the utilities slot.
  const profileEnabled = !unavEnabled && rawProfileElem !== null;
  const breadcrumbAnchors = [
    ...document.querySelectorAll<HTMLAnchorElement>('.breadcrumbs ul > li > a')
  ];
  input.convertStageLinks?.({
    anchors: breadcrumbAnchors,
    hostname: window.location.hostname,
    href: window.location.href,
  });

  const brandConciergeBlock = await resolveBrandConciergeBlock(mainNav);

  const gnavData = parseNavigation(
    mainNav,
    unavEnabled,
    profileEnabled,
    await getPlaceholders(),
    promoBarEl,
  );

  if (gnavData instanceof IrrecoverableError) {
    lanaLog(gnavData.message);
    throw gnavData;
  }

  await renderGnav(gnavData)(mountpoint);

  if (gnavData.brandConciergeEnabled && brandConciergeBlock !== null) {
    try {
      await getLoadBrandConcierge()(brandConciergeBlock);
    } catch (error) {
      lanaLog(`Failed to load brand concierge: ${error}`);
    }
  }

  return postRenderingTasks(input, rawProfileElem);
};

export const renderGnav = (
  data: GlobalNavigationData
) => async (
mountpoint: HTMLElement
): Promise<HTMLElement> => {
  const navHTML = renderGnavString(data);
  document.querySelector('main')?.setAttribute('id', 'main-content');
  setSanitizedHTML(mountpoint, navHTML);
  const promoBar = await data.promoBar;
  if (promoBar !== null) {
    const promoWrapper = document.querySelector<HTMLElement>(
      '.feds-promo-aside-wrapper',
    );
    if (promoWrapper !== null) {
      setSanitizedHTML(promoWrapper, renderPromoBar(promoBar));
      promoWrapper.style.display = 'none';
      promoWrapper.classList.add(`feds-promo-bar--${promoBar.theme}`);

      const promoBarEl = promoWrapper.querySelector<HTMLElement>('.feds-promo-bar');
      const barBgColor = promoBarEl?.style.backgroundColor ?? '';
      if (barBgColor !== '') promoWrapper.style.backgroundColor = barBgColor;
      await initMerchLinks(promoWrapper);
    }
  }
  if (data.components.filter(c => c.type !== 'Brand').length === 0) mountpoint.classList.add('thin');
  if (data.darkFont) mountpoint.classList.add('dark-font');
  // SmallMenu triggers also carry `.mega-menu` (see SmallMenu/Render), so
  // exclude `.small-menu` to stay aligned 1:1 with megaMenuComponents.
  const megaMenus = [
    ...mountpoint.querySelectorAll('.mega-menu:not(.small-menu) ~ .feds-popup:not(.small-menu)')
  ]
  megaMenus.forEach(mm => {
    mm.replaceChildren();
  });
  const megaMenuComponents = data.components.filter(com => com.type === "MegaMenu");
  const mmPromises = megaMenuComponents.map(com => com.content);
  await Promise.all(mmPromises.map(async (mmPromise, idx) => {
    try {
      const [content] = await mmPromise;
      const extraData: MegaMenuExtraData = { type: "MegaMenuExtraData", breadcrumbs: data.breadcrumbs };
      setSanitizedHTML(
        megaMenus[idx],
        popup(content, megaMenus[idx].id, extraData),
      );
    } catch (error) {
      lanaLog(`Failed to render mega menu: ${error}`);
    }
  }));

  const smallMenus = [
    ...mountpoint.querySelectorAll('button.small-menu ~ .feds-popup')
  ];
  const smallMenuComponents = data.components.filter(com => com.type === "SmallMenu");
  smallMenuComponents.forEach((com, idx) => {
    const [content] = com.content;
    setSanitizedHTML(
      smallMenus[idx],
      smallMenuPopup(content, smallMenus[idx].id),
    );
  });

  return mountpoint;
};


export const renderGnavString = ({
  components,
  breadcrumbs,
  productCTA,
  unavEnabled,
  profileEnabled,
  placeholders,
  localnav,
  brandConciergeEnabled,
  notificationsEnabled,
}: GlobalNavigationData
): string => {
  const menuComponents = components.filter((c) => c.type !== "Brand");
  // In localnav mobile, the menu-wrapper is repurposed as the localnav bar
  // (a thin clickable strip below the main nav row that expands inline to
  // reveal the remaining mega-menu entries), and the hamburger opens that
  // same mega menu's popup directly. Its label mirrors the mega menu's own
  // title rather than the breadcrumbs, matching how milo global-navigation
  // sources a standalone local nav's label from the nav's own first item -
  // clients without breadcrumbs can still have a localnav.
  const firstMegaMenu = localnav
    ? menuComponents.find((c) => c.type === "MegaMenu") ?? null
    : null;
  // Like milo, a localnav without a mega menu has no hamburger: the bar is
  // labeled by the first item, which stays in the list relabeled "Overview".
  const isLocalnavWithoutMegaMenu = localnav && firstMegaMenu === null;
  const localnavBarItem = ((): Component | null => {
    if (firstMegaMenu !== null)
      return menuComponents[menuComponents.indexOf(firstMegaMenu) + 1] ?? null;
    return isLocalnavWithoutMegaMenu ? menuComponents[0] ?? null : null;
  })();
  // The bar item's label lives in a different field per component type:
  // MegaMenu/SmallMenu use `title`, Link/CTAs use `text`, Text uses `content`.
  const localnavBarLabel = ((): string => {
    if (localnavBarItem === null) return '';
    if ('title' in localnavBarItem) return localnavBarItem.title;
    if ('text' in localnavBarItem) return localnavBarItem.text;
    if ('content' in localnavBarItem) return localnavBarItem.content;
    return '';
  })();
  const renderMenuComponent = (c: Component, index: number): HTML => (
    c === localnavBarItem
      ? component(withLocalnavOverviewLabel(c, placeholders), index)
      : component(c, index)
  );
  // Clone the trailing CTA (last CTA-typed column) into a toolbar slot so it
  // stays visible beside the hamburger, not only inside the drawer.
  const ctaComponents = components.filter(
    (c) => c.type === 'PrimaryCTA' || c.type === 'SecondaryCTA'
  );
  const [trailingCta] = ctaComponents.slice(-1);
  const pinnedCtaHTML = trailingCta !== undefined
    ? `<div class="feds-pinned-cta">${component(trailingCta)}</div>`
    : '';

  return `
<nav class="${localnav ? "localnav" : ""}${isLocalnavWithoutMegaMenu ? " localnav--without-mega-menu" : ""}">
  <div class="feds-backdrop" aria-hidden="true"></div>
  <a href="#main-content" class="feds-skip-link"><span class="feds-skip-link-text">${placeholders.get('skip-to-main') ?? 'Skip to main content'}</span>${icons.chevronRightBold}</a>
  <ul role="presentation">
    ${((): string => {
      const brandComponent = components.find((c) =>
        c.type === "Brand"
      ) ?? null;
      // In localnav mode the hamburger should open the first mega menu's
      // popup directly rather than the menu wrapper / gnav-items list.
      const toggleControlsId = firstMegaMenu !== null
        ? sanitize(firstMegaMenu.title)
        : 'feds-menu-wrapper';
      const toggleButton = `
        <button
          class="feds-nav-toggle"
          type="button"
          aria-label="Navigation menu"
          daa-ll="hamburgermenu|open"
          aria-expanded="false"
          aria-controls="${toggleControlsId}"
        >
          <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 14 7" fill="currentColor" aria-hidden="true">
            <path d="M13.25 5.5H0.75C0.33594 5.5 0 5.83594 0 6.25C0 6.66406 0.33594 7 0.75 7H13.25C13.6641 7 14 6.66406 14 6.25C14 5.83594 13.6641 5.5 13.25 5.5Z"/>
            <path d="M0.75 1.5H13.25C13.6641 1.5 14 1.16406 14 0.75C14 0.33594 13.6641 0 13.25 0H0.75C0.33594 0 0 0.33594 0 0.75C0 1.16406 0.33594 1.5 0.75 1.5Z"/>
          </svg>
        </button>
      `.trim();

      const brandHTML = brandComponent ? component(brandComponent) : "";

      const menuItemsHTMLList = ((): HTML[] => {
        const lis = menuComponents
                       .map((c, index) => `<li>${renderMenuComponent(c, index)}</li>`);
        const [first, ...rest] = lis;
        return localnav ? [first, '<li class="divider"></li>', ...rest] : lis;
      })();
      const menuItemsHTML = menuItemsHTMLList.join('');

      return `
        <li class="feds-brand-wrapper">
          ${isLocalnavWithoutMegaMenu ? '' : toggleButton}
          ${brandHTML}
        </li>
        <li
          id="feds-menu-wrapper"
          class="feds-menu-wrapper"
        >
          ${localnav ? `
            <button
              class="feds-localnav-bar"
              type="button"
              aria-controls="feds-menu-wrapper"
              aria-expanded="false"
              daa-ll="localnav-bar|Open"
            ><span class="feds-localnav-bar-label">${localnavBarLabel}</span></button>
          ` : ''}
          <ul class="feds-gnav-items">
            ${menuItemsHTML}
          </ul>
        </li>
      `.trim();
    })()}
  </ul>
  ${brandConciergeEnabled ? '<div class="feds-bc-wrapper"></div>' : ''}
  ${pinnedCtaHTML}
  ${productCTA === null ? '' : productEntryCTA(productCTA)}
  ${notificationsEnabled ? '<div class="feds-notifications-wrapper"></div>' : ''}
  ${profileEnabled
    ? '<div data-cs-mask class="feds-profile-new"></div>'
    : unavEnabled ? '<div class="feds-utilities"></div>' : ''}
  ${breadcrumbs === null ? '' : renderBreadcrumbs(breadcrumbs)}
  <a href="#" class="trap-focus-gnav">.</a>
</nav>
`;
};

export const postRenderingTasks = async (
  input: Input,
  rawProfileElem: Element | null = null,
): Promise<GlobalNavigation | IrrecoverableError> => {
  const errors = new Set<RecoverableError>();

  const activeLink = findActiveLink(input.mountpoint);
  const activeDropDown = activeLink?.closest('ul.feds-gnav-items > li');
  activeDropDown?.classList.add('active-element');
  initGnavItemsStaggerIndex(input.mountpoint);
  initActiveTopLevelLinkClosesLocalnav(input.mountpoint);
  initPromoBarHeight(input.mountpoint);
  initLanguageBannerOffset(input.mountpoint);
  initBranchBannerOffset(input.mountpoint);
  initClickListeners(input.mountpoint);
  wirePopups(input.mountpoint);
  initLightDismiss(input.mountpoint);
  initKeyboardNav(input.mountpoint);
  initAriaToggleListeners(input.mountpoint);
  initPopoverCloseOnResize(input.mountpoint);
  initHeaderScrollState(input.mountpoint);
  initHeaderAnalytics(input.mountpoint, input.mepMartech ?? '');
  initCompactOverflow(input.mountpoint);
  initPromoCountdownInPromoBar();
  const merchLinkErrors = await initMerchLinks(input.mountpoint);
  merchLinkErrors.forEach((error: RecoverableError) => {
    errors.add(error);
    lanaLog(error.message);
  });

  // Runs before `await loadUnav` so a slow/failed UNAV load can't delay it.
  initEventRegistrationGating(input.mountpoint);
  const profileEnabled = !input.unavEnabled && rawProfileElem !== null;
  let reloadUnav = (): void => {};
  let reloadProfile = (): void => {};

  if (profileEnabled) {
    const profile = await loadProfile(input.mountpoint, rawProfileElem);
    if (profile instanceof RecoverableError) {
      errors.add(profile);
      lanaLog(profile.message);
    } else {
      reloadProfile = (): void => { void profile.reloadProfile(); };
    }
  } else if (input.unavEnabled) {
    const unav = await loadUnav(input.mountpoint, {
      countryCode: input.countryCode,
      imsReady: input.imsReady,
      fetchAUPSDKInstance: getHostFetchAUPSDKInstance(input),
    });
    if (unav instanceof RecoverableError) {
      errors.add(unav);
      lanaLog(unav.message);
    } else {
      unav.errors.forEach((error: RecoverableError) => errors.add(error));
      reloadUnav = unav.reloadUnav;
    }
    initPopoverCloseOnUnavInteraction(input.mountpoint);
  }

  const localnavMarginTop = 8;
  const breadcrumbs = input.mountpoint.querySelector('nav > ul.feds-breadcrumbs');
  const mobileLocalnav = input.mountpoint.querySelector('li.feds-menu-wrapper');
  type NavType = "Default" | "DefaultCompact" | "Localnav" | "LocalnavCompact";
  const getGnavHeight = (): number => {
    const nav = input.mountpoint.firstElementChild;
    if (!nav) return 0;
    const navType = ((): NavType => {
      const isCompact = input.mountpoint.classList.contains('is-compact') || !isDesktop.matches;
      const defaultOrLocalnav = nav.classList.contains('localnav')
        ? "Localnav"
        : "Default";
      return `${defaultOrLocalnav}${isCompact ? "Compact" : ""}`;
    })();
    const breadcrumbsHeight = breadcrumbs
      ? (breadcrumbs as HTMLElement).offsetHeight
      : 0;
    const navHeight = (nav as HTMLElement).offsetHeight;
    const mobileLocalnavHeight = mobileLocalnav
      ? (mobileLocalnav as HTMLElement).offsetHeight
      : 0;
    switch (navType) {
      case "Default":
      case "DefaultCompact":
      case "Localnav": return navHeight + breadcrumbsHeight + localnavMarginTop;
      case "LocalnavCompact": return navHeight + mobileLocalnavHeight + localnavMarginTop;
      default: navType satisfies never;
    }
    return 0;
  };

  const fedsWindow = window as unknown as {
    feds?: { nav?: Partial<Pick<GlobalNavigation, "getGnavHeight">> };
  };
  fedsWindow.feds ??= {};
  fedsWindow.feds.nav ??= {};
  fedsWindow.feds.nav.getGnavHeight = getGnavHeight;

  return {
    closeEverything: () => closePopovers(input.mountpoint),
    reloadUnav,
    reloadProfile,
    errors,
    setGnavTopPosition: (_): void => {},
    getGnavTopPosition: (): number => 0,
    getGnavHeight,
  };
};

const initAriaToggleListeners = (mountpoint: HTMLElement): void => {
  const menuWrapper = mountpoint.querySelector<HTMLElement>('#feds-menu-wrapper');
  const navToggle = mountpoint.querySelector<HTMLElement>('.feds-nav-toggle');
  const nav = mountpoint.querySelector<HTMLElement>('nav');

  // Lenis should only be blocked from hijacking scroll while something
  // scrollable (the mobile drawer or a mega-menu popup) is actually open —
  // not permanently. Recomputed on every open/close instead of set once.
  const updateNavLenisPrevent = (): void => {
    nav?.toggleAttribute('data-lenis-prevent', mountpoint.querySelector(`.${IS_OPEN_CLASS}`) !== null);
  };

  menuWrapper?.addEventListener('toggle', () => {
    const isOpen = menuWrapper.classList.contains(IS_OPEN_CLASS);
    // Only reflect open-state on the hamburger when it actually controls the
    // menu-wrapper. In localnav the hamburger's aria-controls points at the
    // first mega-menu's popup (the menu-wrapper is opened via the localnav
    // bar instead), so reflecting menu-wrapper state on the hamburger here
    // would be incorrect.
    if (navToggle?.getAttribute('aria-controls') === 'feds-menu-wrapper') {
      navToggle.setAttribute('aria-expanded', String(isOpen));
      navToggle.setAttribute(
        'daa-ll',
        isOpen ? 'hamburgermenu|close' : 'hamburgermenu|open'
      );
    }
    if (isOpen) menuWrapper.classList.add('feds-menu-active');

    updateNavLenisPrevent();
  });

  menuWrapper?.addEventListener('transitionend', () => {
    if (!menuWrapper.classList.contains(IS_OPEN_CLASS)) {
      menuWrapper.classList.remove('feds-menu-active');
    }
  });

  const megaMenuPopovers = mountpoint.querySelectorAll<HTMLElement>('.feds-popup');
  megaMenuPopovers.forEach(popup => {
    popup.addEventListener('toggle', () => {
      const trigger = mountpoint.querySelector<HTMLElement>(
        `[aria-controls="${popup.id}"]`
      );
      const isOpen = popup.classList.contains(IS_OPEN_CLASS);
      trigger?.setAttribute('aria-expanded', String(isOpen));
      trigger?.setAttribute('daa-ll', isOpen ? 'header|Close' : 'header|Open');
      updateNavLenisPrevent();
    });
  });
};

const initPopoverCloseOnResize = (mountpoint: HTMLElement): void => {
  isDesktop.addEventListener('change', () => {
    closePopovers(mountpoint);
  });
};

const initPopoverCloseOnUnavInteraction = (mountpoint: HTMLElement): void => {
  // Delegate to the container to handle late IMS recovery.
  const utilities = mountpoint.querySelector('.feds-utilities');
  const closeOnInteraction = (event: Event): void => {
    if (!(event.target instanceof Element) || !event.target.closest('#universal-nav')) return;
    if (event instanceof KeyboardEvent && event.key !== 'Enter') return;
    closePopovers(mountpoint);
  };
  utilities?.addEventListener('click', closeOnInteraction);
  utilities?.addEventListener('keydown', closeOnInteraction);
};

const initHeaderScrollState = (mountpoint: HTMLElement): void => {
  const header = mountpoint.closest("header");
  if (!header) {
    return;
  }

  const menuWrapper = mountpoint.querySelector<HTMLElement>("#feds-menu-wrapper");
  const isMenuOpen = (): boolean => isPopupOpen(menuWrapper);

  const nav = mountpoint.querySelector<HTMLElement>("nav");
  const isLocalnav = (): boolean => nav?.classList.contains("localnav") ?? false;

  // Track the most recent "queued add" so a subsequent toggle can cancel it.
  // Prevents a race where the user re-opens the bar mid-slide-down and the
  // deferred add still fires, applying `feds-header-scrolled` over an
  // already-open menu.
  let pendingAddCleanup: (() => void) | null = null;
  const cancelPendingAdd = (): void => {
    if (pendingAddCleanup !== null) {
      pendingAddCleanup();
      pendingAddCleanup = null;
    }
  };

  const updateHeaderState = (
    scrolledPast: boolean,
    fromToggle: boolean = false
  ): void => {
    cancelPendingAdd();
    if (isMenuOpen() || !scrolledPast) {
      header.classList.remove("feds-header-scrolled", "feds-localnav-closing");
      return;
    }
    header.classList.add("feds-header-scrolled");
    // Closing the localnav bar in scrolled state: nav's `margin-top` animates
    // from -64px back to 0 over 0.3s (see localnav.css). The
    // `feds-header-scrolled` class is needed immediately for color (the bar
    // title would otherwise flash from dark back to its default light shade
    // during the slide-down). The `feds-localnav-closing` marker class is
    // added in tandem for the duration of the transition and removed on
    // `transitionend`.
    if (fromToggle && isLocalnav() && nav !== null) {
      header.classList.add("feds-localnav-closing");
      const onTransitionEnd = (event: TransitionEvent): void => {
        if (event.target !== nav || event.propertyName !== "margin-top") return;
        nav.removeEventListener("transitionend", onTransitionEnd);
        pendingAddCleanup = null;
        header.classList.remove("feds-localnav-closing");
      };
      nav.addEventListener("transitionend", onTransitionEnd);
      pendingAddCleanup = (): void => {
        nav.removeEventListener("transitionend", onTransitionEnd);
        header.classList.remove("feds-localnav-closing");
      };
    }
  };

  const promoBarEl = document.querySelector<HTMLElement>(
    '.feds-promo-aside-wrapper .feds-promo-bar',
  );
  // Measured live (rather than hardcoded per state) since the promo bar's
  // actual height differs across mobile, tablet, and desktop breakpoints.
  const promoBarElMinHeight = (): number =>
    promoBarEl === null ? 70 : promoBarEl.getBoundingClientRect().height;

  const getScrollThreshold = (): number =>
    promoBarEl !== null ? promoBarElMinHeight() : 20;

  let scrolledPast = window.scrollY > getScrollThreshold();
  let scrollRafId: number | null = null;

  // Set the initial state synchronously before the first paint.
  updateHeaderState(scrolledPast);

  const onScroll = (): void => {
    if (scrollRafId !== null) return;
    scrollRafId = requestAnimationFrame(() => {
      scrollRafId = null;
      const next = window.scrollY > getScrollThreshold();
      if (next === scrolledPast) return;
      scrolledPast = next;
      updateHeaderState(scrolledPast);
    });
  };

  window.addEventListener("scroll", onScroll, { passive: true });

  menuWrapper?.addEventListener("toggle", () =>
    updateHeaderState(scrolledPast, true)
  );
};

const initHeaderAnalytics = (
  mountpoint: HTMLElement,
  mepMartech: string
): void => {
  const header = mountpoint.closest("header");
  if (header === null) return;
  header.setAttribute('daa-lh', `gnav|${getExperienceName()}${mepMartech}`);
};

// Min gap (px) between the brand/hamburger and the trailing CTA group.
const CTA_OVERFLOW_GAP = 32;

const initCompactOverflow = (mountpoint: HTMLElement): void => {
  const header = mountpoint.closest<HTMLElement>('header.global-navigation');
  if (!header) return;

  const nav = mountpoint.querySelector<HTMLElement>('nav');
  const brandWrapper = mountpoint.querySelector<HTMLElement>('.feds-brand-wrapper');
  const gnavItems = mountpoint.querySelector<HTMLElement>('.feds-gnav-items');
  const utilities = mountpoint.querySelector<HTMLElement>('.feds-utilities');
  const bcWrapper = mountpoint.querySelector<HTMLElement>('.feds-bc-wrapper, .feds-profile-new');
  const pinnedCta = mountpoint.querySelector<HTMLElement>('.feds-pinned-cta');
  const productCta = mountpoint.querySelector<HTMLElement>('.feds-product-entry-cta');

  const check = (): void => {
    // Skip re-measuring while a menu/popup is open. Stripping the state classes
    // below (even momentarily) drops the compact-scoped body scroll-lock (see
    // `body:has(header.global-navigation.is-compact ...)` in styles.css), which
    // lets the scrollbar flash back in and changes `header`'s width — the very
    // thing this function's ResizeObserver watches — retriggering check() in an
    // infinite loop that resets the gnav reveal animation mid-flight. Nothing
    // about open/closed state changes whether the content overflows, so just
    // wait for the next real resize or breakpoint change.
    if (header.querySelector('.feds-menu-wrapper.is-open, .feds-popup.is-open')) return;

    const mobile = !isDesktop.matches;

    // Strip both classes first so measurements read natural (all-shown) widths.
    header.classList.remove('is-compact', 'feds-cta-overflow');

    // Stage 1: is-compact (desktop overflow collapse; mobile uses the drawer).
    if (!mobile) {
      // The flex list's offsetWidth can be smaller than its content.
      const brandWidth = brandWrapper === null
        ? 0
        : Math.max(brandWrapper.offsetWidth, brandWrapper.scrollWidth);
      const itemsWidth = getIntrinsicItemsWidth(gnavItems);
      const utilitiesWidth = utilities === null
        ? 0
        : Math.max(utilities.offsetWidth, utilities.scrollWidth);
      const ctaWidth = productCta === null
        ? 0
        : Math.max(productCta.offsetWidth, productCta.scrollWidth);
      const bcWidth = bcWrapper === null
        ? 0
        : Math.max(bcWrapper.offsetWidth, bcWrapper.scrollWidth);
      const contentWidth = brandWidth + itemsWidth +
        utilitiesWidth + ctaWidth + bcWidth + 40;
      header.classList.toggle('is-compact', contentWidth > header.clientWidth);
    }

    // Stage 2: when collapsed, hide both toolbar CTAs if they'd overlap the
    // hamburger (they stay reachable in the drawer).
    const collapsed = mobile || header.classList.contains('is-compact');
    if (!collapsed || (!pinnedCta && !productCta)) return;
    const needed = (brandWrapper?.offsetWidth ?? 0)
      + (bcWrapper?.offsetWidth ?? 0)
      + (pinnedCta?.offsetWidth ?? 0)
      + (productCta?.offsetWidth ?? 0)
      + (utilities?.offsetWidth ?? 0) + CTA_OVERFLOW_GAP;
    const available = nav?.clientWidth ?? header.clientWidth;
    header.classList.toggle('feds-cta-overflow', needed > available);
  };

  const observer = new ResizeObserver(check);
  observer.observe(header);
  // UNAV can resize without changing the header's border box.
  if (utilities !== null) observer.observe(utilities);
  if (bcWrapper !== null) observer.observe(bcWrapper);
  isDesktop.addEventListener('change', check);
  mountpoint.addEventListener(MERCH_RESOLVED_EVENT, check);
  check();
};

const isCurrentPageHref = (href: string): boolean => {
  const url = `${window.location.origin}${window.location.pathname}`;
  return href === url
      || href.startsWith(`${url}?`)
      || href.startsWith(`${url}#`);
};

const findActiveLink = (
  mountpoint: HTMLElement
): HTMLAnchorElement | null => {
  // In localnav the first top-level <li> (before the divider) is the mega
  // menu whose title also labels the localnav bar — it represents the
  // section itself rather than a sibling destination, so it's excluded here
  // and only links after the divider are eligible to be marked active.
  const isLocalnav = mountpoint.querySelector('nav.localnav') !== null;
  return [...mountpoint.querySelectorAll<HTMLAnchorElement>('a:not(.feds-skip-link)')]
    .filter(a => !a.closest('.feds-breadcrumbs'))
    .filter(a => !isLocalnav || a.closest('ul.feds-gnav-items > li:first-child') === null)
    .find(a => isCurrentPageHref(a.href)) ?? null;
};

/**
 * Sets a `--i` CSS custom property on each top-level `<li>` inside every
 * `ul.feds-gnav-items`, indexed from 0. This drives the staggered
 * open/close animations in `styles.css` via
 * `animation-delay: calc(var(--i) * ...)`, removing the need for a
 * hand-maintained `nth-child` table that must be extended every time the
 * menu grows.
 */
const initGnavItemsStaggerIndex = (mountpoint: HTMLElement): void => {
  const lists = mountpoint.querySelectorAll<HTMLUListElement>('ul.feds-gnav-items');
  lists.forEach(list => {
    const items = list.querySelectorAll<HTMLLIElement>(':scope > li');
    items.forEach((li, index) => {
      li.style.setProperty('--i', String(index));
    });
  });
};

/**
 * In localnav mode, clicking a TOP-LEVEL localnav link whose href points to
 * the current page (the very same URL, with optional ?query) is redundant —
 * the page is already loaded. Instead of triggering a no-op navigation, we
 * suppress the default and close the localnav so the user sees the page
 * they're already on. Scope is strictly limited to
 * `nav.localnav ul.feds-gnav-items > li > a`; nested links (mega-menu
 * popups, links-card, CTAs, breadcrumbs, etc.) are left untouched and
 * continue to navigate normally. Hash-only same-page links also navigate
 * normally (so in-page anchor jumps still work) while still closing the
 * localnav.
 */
// eslint-disable-next-line max-len
const initActiveTopLevelLinkClosesLocalnav = (mountpoint: HTMLElement): void => {
  const localnav = mountpoint.querySelector('nav.localnav');
  if (localnav === null) return;
  const topLevelAnchors = localnav.querySelectorAll<HTMLAnchorElement>(
    'ul.feds-gnav-items > li > a'
  );
  topLevelAnchors.forEach(anchor => {
    if (!isCurrentPageHref(anchor.href)) return;
    anchor.addEventListener('click', (event) => {
      // Defensive: ensure DOM still matches the structural contract at
      // click-time (guards against late mutations broadening scope).
      const target = event.currentTarget as HTMLAnchorElement;
      if (!target.matches('ul.feds-gnav-items > li > a')) return;
      if (target.closest('nav')?.classList.contains('localnav') !== true) return;

      const href = target.href;
      const url = `${window.location.origin}${window.location.pathname}`;
      const isHashOnly = href.startsWith(`${url}#`);
      if (!isHashOnly) {
        event.preventDefault();
        event.stopPropagation();
      }
      closePopovers(mountpoint);
      const focusTarget
        = mountpoint.querySelector<HTMLElement>('.feds-localnav-bar')
        ?? mountpoint.querySelector<HTMLElement>('.feds-nav-toggle');
      focusTarget?.focus();
    });
  });
};

// Polls (rather than listening for a `transitionend`) since the host page
// may set body opacity via a CSS transition, an instant class toggle, or an
// inline style — a poll catches all three without coupling to whichever
// mechanism the host happens to use.
const waitUntilVisible = (callback: () => void): void => {
  const isBodyVisible = (): boolean =>
    window.getComputedStyle(document.body).opacity === '1';

  const check = (): void => {
    if (isBodyVisible()) {
      // Inline arrow so the timer can only ever receive a function, never a
      // string that would be evaluated as code.
      setTimeout(() => callback(), 1000);
    } else {
      requestAnimationFrame(check);
    }
  };
  check();
};

/**
 * Injects a countdown timer into every `.feds-promo-bar-inner` slot of a
 * `minimized` / `maximized` PromoBar.  Reads the `gnav-promo-countdown`
 * meta tag for the start/end window; no-ops silently when the tag is absent,
 * malformed, or the current time is outside the window.
 */
const initPromoCountdownInPromoBar = (): void => {
  const promoBar = document.querySelector<HTMLElement>(
    '.feds-promo-aside-wrapper .feds-promo-bar',
  );
  if (promoBar === null) return;

  const isDark = promoBar.classList.contains('feds-promo-bar--dark');

  if (promoBar.classList.contains('feds-promo-bar--minimized')) {
    const inners = promoBar.querySelectorAll<HTMLElement>('.feds-promo-bar-inner');
    inners.forEach((inner) => {
      const textEl = inner.querySelector<HTMLElement>('.feds-promo-bar-text');
      if (textEl === null) return;
      initPromoCountdown(inner, textEl, isDark);
    });
    return;
  }

  // Maximized / maximized-release: the icon lives inside the product
  // container, so the timer is grouped there, before the product name.
  const containers = promoBar.querySelectorAll<HTMLElement>(
    '.feds-promo-product-container',
  );

  containers.forEach((container) => {
    const productName = container.querySelector<HTMLElement>(
      ':scope > .feds-promo-bar-product',
    );
    if (productName === null) return;
    initPromoCountdown(container, productName, isDark);
    const cdt = isDark ? '.feds-cdt--dark' : '.feds-cdt'
    if (container.querySelector(cdt) == null) return;
    productName.style.setProperty('display', 'none');

    const restore = new MutationObserver(() => {
      if (container.querySelector(cdt) != null) return;
      productName.style.removeProperty('display');
      restore.disconnect();
    });
    restore.observe(container, { childList: true, subtree: true});

    const cleanup = new MutationObserver(() => {
      if (document.contains(container)) return;
      restore.disconnect();
      cleanup.disconnect();
    });
    cleanup.observe(document.body, { childList: true, subtree: true});

  });

};

const initPromoBarHeight = (mountpoint: HTMLElement): void => {
  const promoBar = document.querySelector<HTMLElement>(
    '.feds-promo-aside-wrapper .feds-promo-bar',
  );
  if (promoBar === null) return;

  const promoWrapper = promoBar.closest<HTMLElement>(
    '.feds-promo-aside-wrapper',
  );
  if (promoWrapper === null) return;

  waitUntilVisible(() => {
    promoWrapper.style.display = '';
    promoWrapper.classList.add('feds-promo-bar--reveal');
  });

  // header.global-navigation is `position: sticky`, so it renders below the
  // promo bar and scrolls with the page natively — no JS or CSS animation
  // needed for that part. --feds-promo-bar-height only feeds the extra
  // offset that popups/the mobile drawer need while the promo is still
  // showing (see styles.css); re-measured on resize in case the promo
  // reflows.
  //
  // Measure the wrapper, not the inner .feds-promo-bar: the wrapper is
  // what the reveal animation clips via max-height, so its offsetHeight
  // ramps up in step with the visible box. The inner bar is never
  // height-constrained, so it reports its full natural height the instant
  // display flips from `none` — which would snap --feds-promo-bar-height
  // (and the body padding-top it drives) to its final value a full
  // animation ahead of what's actually visible on screen.
  const updateHeight = (): void => {
    document.documentElement.style.setProperty(
      '--feds-promo-bar-height',
      `${promoWrapper.offsetHeight}px`,
    );
  };
  new ResizeObserver(updateHeight).observe(promoWrapper);
  updateHeight();

  // Toggles `.feds-promo-showing` on <header> so the popup/drawer offset
  // overrides only apply while the promo is actually on screen. Fires only
  // when the promo bar enters/exits the viewport — not per scroll frame —
  // avoiding the layout-thrashing a continuous scroll listener caused here
  // previously.
  const header = mountpoint.closest<HTMLElement>('header.global-navigation');
  if (header === null) return;
  new IntersectionObserver(([entry]) => {
    header.classList.toggle('feds-promo-showing', entry.isIntersecting);
  }).observe(promoBar);
};

// header.global-navigation is `position: sticky`, so it renders below
// .language-banner and scrolls with the page natively —
// This toggles `.feds-banner-showing` on <header> so the
// popup/drawer offset overrides in styles.css apply while the banner is
// active. Fires only on enter/exit, not per scroll frame.
const initLanguageBannerOffset = (mountpoint: HTMLElement): void => {
  const header = mountpoint.closest<HTMLElement>('header.global-navigation');
  if (header === null) return;

  const observe = (banner: HTMLElement): void => {
    new IntersectionObserver(([entry]) => {
      header.classList.toggle('feds-banner-showing', entry.isIntersecting);
    }).observe(banner);
  };

  const banner = document.querySelector<HTMLElement>('.language-banner');
  if (banner) { observe(banner); return; }

  // Banner is added asynchronously after geo/language detection.
  const mo = new MutationObserver((_, observer) => {
    const el = document.querySelector<HTMLElement>('.language-banner');
    if (!el) return;
    observer.disconnect();
    observe(el);
  });
  mo.observe(document.body, { childList: true });
};

const BRANCH_BANNER_ID = 'branch-banner-iframe';

// #branch-banner-iframe is injected by the branch/PR preview overlay
// (unrelated to gnav's own render) and can be added or removed at any point.
// It's either `position: fixed` (must stay on screen permanently, e.g. "now
// previewing branch X") or in normal flow (pushes header down, then scrolls
// away once header's `position: sticky` takes over — same as the promo bar /
// language banner above). Unlike those two, the branch banner isn't measured
// against a hardcoded height — it's authored by an external tool, so its
// height is read live via ResizeObserver, same as the promo bar.
const initBranchBannerOffset = (mountpoint: HTMLElement): void => {
  const header = mountpoint.closest<HTMLElement>('header.global-navigation');
  if (header === null) return;

  let resizeObserver: ResizeObserver | null = null;
  let intersectionObserver: IntersectionObserver | null = null;

  const teardown = (): void => {
    resizeObserver?.disconnect();
    intersectionObserver?.disconnect();
    resizeObserver = null;
    intersectionObserver = null;
    header.classList.remove('feds-branch-banner-fixed', 'feds-branch-banner-showing');
    document.documentElement.style.removeProperty('--feds-branch-banner-height');
  };

  const setup = (banner: HTMLElement): void => {
    const updateHeight = (): void => {
      document.documentElement.style.setProperty(
        '--feds-branch-banner-height',
        `${banner.offsetHeight}px`,
      );
    };
    resizeObserver = new ResizeObserver(updateHeight);
    resizeObserver.observe(banner);
    updateHeight();

    // A fixed banner never leaves the viewport, so its offset is permanent —
    // no IntersectionObserver needed. An in-flow banner behaves like the
    // promo bar / language banner: only "showing" until it scrolls past.
    if (window.getComputedStyle(banner).position === 'fixed') {
      header.classList.add('feds-branch-banner-fixed');
      return;
    }
    intersectionObserver = new IntersectionObserver(([entry]) => {
      header.classList.toggle('feds-branch-banner-showing', entry.isIntersecting);
    });
    intersectionObserver.observe(banner);
  };

  const existing = document.getElementById(BRANCH_BANNER_ID);
  if (existing) setup(existing);

  // The preview overlay can add/remove the banner at any point in the page's
  // lifetime (not just once, like the language banner), so this observer is
  // kept running indefinitely rather than disconnecting after first sight.
  new MutationObserver((mutations) => {
    mutations.forEach((mutation) => {
      mutation.addedNodes.forEach((node) => {
        const isBanner = node instanceof HTMLElement
          && node.id === BRANCH_BANNER_ID;
        if (!isBanner) return;
        // Let the banner's own styles/layout settle before reading its
        // computed position/height.
        requestAnimationFrame(() => setup(node));
      });
      mutation.removedNodes.forEach((node) => {
        const isBanner = node instanceof HTMLElement
          && node.id === BRANCH_BANNER_ID;
        if (isBanner) teardown();
      });
    });
  }).observe(document.body, { childList: true });
};
